CREATE TABLE shared_locations(trip_id VARCHAR2(36) REFERENCES trips(id),account_id VARCHAR2(36),latitude NUMBER(10,7) NOT NULL,longitude NUMBER(10,7) NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,PRIMARY KEY(trip_id,account_id));
CREATE TABLE replanning_proposals(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL REFERENCES trips(id),itinerary_id VARCHAR2(36) NOT NULL REFERENCES itinerary_versions(id),reason VARCHAR2(500) NOT NULL,base_version NUMBER(19) NOT NULL,status VARCHAR2(20) NOT NULL CHECK(status IN ('PROPOSED','APPLIED','REJECTED')),created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
